export const DEAL_STAGES = [
  'lead',
  'qualified',
  'active',
  'negotiation',
  'closed_won',
  'closed_lost',
] as const;

export type DealStage = (typeof DEAL_STAGES)[number];

export const DEAL_INITIAL_STAGES: readonly DealStage[] = ['lead', 'qualified'];

export const DEAL_STAGE_TRANSITIONS: Readonly<
  Record<DealStage, readonly DealStage[]>
> = {
  lead: ['qualified', 'closed_lost'],
  qualified: ['active', 'closed_lost'],
  active: ['negotiation', 'closed_lost'],
  negotiation: ['closed_won', 'closed_lost'],
  closed_won: [],
  closed_lost: ['lead'],
};

export function isDealStage(stage: string): stage is DealStage {
  return DEAL_STAGES.includes(stage as DealStage);
}

export function getAllowedStageTransitions(
  stage: DealStage,
): readonly DealStage[] {
  return DEAL_STAGE_TRANSITIONS[stage];
}
