import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { DataSource, EntityManager, In } from 'typeorm';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactEntity } from '../contact/contact.entity';
import {
  CreateDealDto,
  DealContactLinkInputDto,
  DealListQueryDto,
  TransitionDealStageDto,
  UpdateDealDto,
} from './dto';
import { DealContactLinkEntity } from './deal-contact-link.entity';
import {
  DealCompanySummary,
  DealContactSummary,
  DealDetailResponseDto,
  DealResponseDto,
} from './dto/response.dto';
import { DealEntity } from './deal.entity';
import {
  DEAL_INITIAL_STAGES,
  DealStage,
  getAllowedStageTransitions,
  isDealStage,
} from './deal-stage';
import { DealRepository } from './deal.repository';

type DealContactRow = {
  dealId: string;
  contactId: string;
  role: string | null;
  contactName: string;
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly dataSource: DataSource,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealDetailResponseDto> {
    const requestedStage = this.parseRequestedStage(dto.stage, 'stage');
    const initialStage = requestedStage ?? 'lead';
    this.assertValidInitialStage(initialStage);

    await this.ensureCompanyExists(dto.companyId);

    const contactLinks = dto.contactLinks ?? [];
    this.assertUniqueContactLinks(contactLinks);

    const hasPrimaryContactInPayload = Object.prototype.hasOwnProperty.call(
      dto,
      'primaryContactId',
    );

    const resolvedPrimaryContactId = this.resolvePrimaryContactId(
      contactLinks,
      dto.primaryContactId,
      hasPrimaryContactInPayload,
    );

    await this.ensureDealContactsAreValid(contactLinks, dto.companyId);

    const savedDealId = await this.dataSource.transaction(async (manager) => {
      const deal = manager.create(DealEntity, {
        name: dto.name,
        value: dto.value,
        stage: initialStage,
        companyId: dto.companyId,
        expectedCloseDate: dto.expectedCloseDate ?? null,
        primaryContactId: resolvedPrimaryContactId,
      });

      const savedDeal = await manager.save(DealEntity, deal);

      if (contactLinks.length > 0) {
        await manager.save(
          DealContactLinkEntity,
          contactLinks.map((link) =>
            manager.create(DealContactLinkEntity, {
              dealId: savedDeal.id,
              contactId: link.contactId,
              role: link.role ?? null,
            }),
          ),
        );
      }

      return savedDeal.id;
    });

    return this.getDealById(savedDealId);
  }

  async getDeals(query: DealListQueryDto) {
    const parsedStage = this.parseRequestedStage(query.stage, 'stage');
    const paginatedDeals = await this.dealRepository.findWithFilter({
      ...query,
      stage: parsedStage,
    });
    const hydratedItems = await this.hydrateDealsWithContacts(
      paginatedDeals.items,
    );

    return {
      ...paginatedDeals,
      items: hydratedItems,
    };
  }

  async getDealById(id: string): Promise<DealDetailResponseDto> {
    const deal = await this.getDealEntityById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);
    const [hydratedDeal] = await this.hydrateDealsWithContacts([deal]);

    const companySummary: DealCompanySummary = {
      id: company.id,
      name: company.name,
      status: company.status,
      industry: company.industry,
    };

    return {
      ...hydratedDeal,
      company: companySummary,
    };
  }

  async updateDeal(
    id: string,
    dto: UpdateDealDto,
  ): Promise<DealDetailResponseDto> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const existingDeal = await this.getDealEntityById(id);
    const targetCompanyId = dto.companyId ?? existingDeal.companyId;

    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.ensureCompanyExists(dto.companyId);
    }

    const hasContactLinksInPayload = Object.prototype.hasOwnProperty.call(
      dto,
      'contactLinks',
    );
    const hasPrimaryContactInPayload = Object.prototype.hasOwnProperty.call(
      dto,
      'primaryContactId',
    );
    const hasStageInPayload = Object.prototype.hasOwnProperty.call(
      dto,
      'stage',
    );

    const existingContactLinks = await this.getDealContactLinks(id);
    const nextContactLinks = hasContactLinksInPayload
      ? (dto.contactLinks ?? [])
      : existingContactLinks.map((link) => ({
          contactId: link.contactId,
          role: link.role ?? undefined,
        }));

    this.assertUniqueContactLinks(nextContactLinks);

    let nextPrimaryContactId: string | null;

    if (hasPrimaryContactInPayload) {
      nextPrimaryContactId = this.resolvePrimaryContactId(
        nextContactLinks,
        dto.primaryContactId ?? null,
        true,
      );
    } else if (hasContactLinksInPayload) {
      const retainedPrimaryContactId =
        existingDeal.primaryContactId &&
        nextContactLinks.some(
          (link) => link.contactId === existingDeal.primaryContactId,
        )
          ? existingDeal.primaryContactId
          : null;

      nextPrimaryContactId = this.resolvePrimaryContactId(
        nextContactLinks,
        retainedPrimaryContactId,
        false,
      );
    } else {
      nextPrimaryContactId = existingDeal.primaryContactId;
    }

    await this.ensureDealContactsAreValid(nextContactLinks, targetCompanyId);

    const nextExpectedCloseDate = Object.prototype.hasOwnProperty.call(
      dto,
      'expectedCloseDate',
    )
      ? (dto.expectedCloseDate ?? null)
      : existingDeal.expectedCloseDate;

    let nextStage: DealStage | undefined;

    if (hasStageInPayload) {
      nextStage = this.parseRequestedStage(dto.stage, 'stage');

      if (!nextStage) {
        throw this.createUnknownStageException('stage');
      }

      this.assertValidStageTransition({
        currentStage: this.getExistingDealStage(existingDeal),
        targetStage: nextStage,
        contactLinksCount: nextContactLinks.length,
        expectedCloseDate: nextExpectedCloseDate,
      });
    }

    await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const linkRepository = manager.getRepository(DealContactLinkEntity);

      const deal = await dealRepository.findOne({ where: { id } });
      if (!deal) {
        throw this.createEntityNotFoundException(id);
      }

      const mergedDeal = dealRepository.merge(deal, {
        name: dto.name,
        value: dto.value,
        stage: hasStageInPayload ? nextStage : undefined,
        companyId: dto.companyId,
        expectedCloseDate: dto.expectedCloseDate,
        primaryContactId: nextPrimaryContactId,
      });

      await dealRepository.save(mergedDeal);

      if (hasContactLinksInPayload) {
        await linkRepository.delete({ dealId: id });

        if (nextContactLinks.length > 0) {
          await linkRepository.save(
            nextContactLinks.map((link) =>
              linkRepository.create({
                dealId: id,
                contactId: link.contactId,
                role: link.role ?? null,
              }),
            ),
          );
        }
      }
    });

    return this.getDealById(id);
  }

  async transitionDealStage(
    id: string,
    dto: TransitionDealStageDto,
  ): Promise<DealDetailResponseDto> {
    const targetStage = this.parseRequestedStage(dto.stage, 'stage');

    if (!targetStage) {
      throw this.createUnknownStageException('stage');
    }

    const deal = await this.getDealEntityById(id);
    const currentStage = this.getExistingDealStage(deal);
    const currentContactLinks = await this.getDealContactLinks(id);

    this.assertValidStageTransition({
      currentStage,
      targetStage,
      contactLinksCount: currentContactLinks.length,
      expectedCloseDate: deal.expectedCloseDate,
    });

    return this.updateDeal(id, {
      stage: targetStage,
    });
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealEntityById(id);
    await this.dealRepository.softDelete(id);
  }

  private async getDealEntityById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw this.createEntityNotFoundException(id);
    }

    return deal;
  }

  private createEntityNotFoundException(id: string): AppException {
    return new AppException({
      statusCode: HttpStatus.NOT_FOUND,
      code: BUSINESS_ERROR_CODES.NOT_FOUND,
      message: `Deal with ID ${id} not found`,
