396	    currentStage,
397	    targetStage,
398	    contactLinksCount,
399	    expectedCloseDate,
400	  }: {
401	    currentStage: DealStage;
402	    targetStage: DealStage;
403	    contactLinksCount: number;
404	    expectedCloseDate: Date | null;
405	  }): void {
406	    if (targetStage === currentStage) {
407	      return;
408	    }
409	
410	    const allowedTargets = getAllowedStageTransitions(currentStage);
411	
412	    if (!allowedTargets.includes(targetStage)) {
413	      throw new AppException({
414	        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
415	        code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
416	        message: `Cannot transition deal stage from ${currentStage} to ${targetStage}.`,
417	        details: {
418	          currentStage,
419	          targetStage,
420	          allowedTargets,
421	        },
422	      });
