     1	import { Injectable } from '@nestjs/common';
     2	import { Brackets, DataSource } from 'typeorm';
     3	import { BaseRepository } from '../../core/database/base.repository';
     4	import { ContactEntity } from './contact.entity';
     5	import { ContactListQueryDto } from './dto';
     6	
     7	@Injectable()
     8	export class ContactRepository extends BaseRepository<ContactEntity> {
     9	  constructor(private dataSource: DataSource) {
    10	    super(ContactEntity, dataSource.createEntityManager());
    11	  }
    12	
    13	  async findWithFilter(query: ContactListQueryDto) {
    14	    const queryBuilder = this.createQueryBuilder('contact');
    15	
    16	    const sortField = query.sort
    17	      ? `contact.${query.sort}`
    18	      : 'contact.createdAt';
    19	    const sortOrder = query.order ? query.order.toUpperCase() : 'DESC';
    20	    queryBuilder.orderBy(sortField, sortOrder as 'ASC' | 'DESC');
    21	
    22	    if (query.companyId) {
    23	      queryBuilder
    24	        .innerJoin(
    25	          'contact_company_links',
    26	          'contactCompanyLink',
    27	          'contactCompanyLink."contactId" = contact.id',
    28	        )
    29	        .andWhere('contactCompanyLink."companyId" = :companyId', {
    30	          companyId: query.companyId,
    31	        });
    32	    }
    33	
    34	    if (query.q) {
    35	      const searchValue = `%${query.q}%`;
    36	      queryBuilder.andWhere(
    37	        new Brackets((qb) => {
    38	          qb.where('contact.name ILIKE :searchValue', { searchValue })
    39	            .orWhere('contact.email ILIKE :searchValue', { searchValue })
    40	            .orWhere('contact.phone ILIKE :searchValue', { searchValue })
    41	            .orWhere('contact.role ILIKE :searchValue', { searchValue });
    42	        }),
    43	      );
    44	    }
    45	
    46	    if (query.role) {
    47	      queryBuilder.andWhere('contact.role = :role', { role: query.role });
    48	    }
    49	
    50	    const offset = query.offset ?? 0;
    51	    const limit = query.limit ?? 20;
    52	
    53	    return queryBuilder
    54	      .distinct(true)
    55	      .skip(offset)
    56	      .take(limit)
    57	      .getManyAndCount();
    58	  }
    59	}
