   231	  async detachCompanyLink(
   232	    contactId: string,
   233	    companyId: string,
   234	    dto: DetachContactCompanyDto,
   235	  ): Promise<ContactResponse> {
   236	    await this.dataSource.transaction(async (manager) => {
   237	      await this.ensureContactExistsForLinkOperation(contactId, manager);
   238	      const linkRepository = manager.getRepository(ContactCompanyLinkEntity);
   239	      const links = await linkRepository.find({ where: { contactId } });
   240	
   241	      const linkToDetach = links.find((link) => link.companyId === companyId);
   242	
   243	      if (!linkToDetach) {
   244	        throw this.createNotFoundException(
   245	          'Contact-Company link not found',
   246	          'ContactCompanyLink',
   247	          `${contactId}:${companyId}`,
   248	        );
   249	      }
   250	
   251	      if (links.length <= 1) {
   252	        throw this.createInvalidLinkStateException(
   253	          'Detaching the last company link is not allowed.',
   254	        );
   255	      }
   256	
   257	      const replacementPrimaryId = dto.newPrimaryCompanyId;
   258	
   259	      if (linkToDetach.isPrimary) {
   260	        if (!replacementPrimaryId) {
---
   261	          throw this.createInvalidLinkStateException(
   262	            'Primary company cannot be detached without selecting another linked company as primary.',
   263	          );
   264	        }
   265	
   266	        if (replacementPrimaryId === companyId) {
   267	          throw this.createInvalidLinkStateException(
   268	            'Replacement primary company must differ from the detached company.',
   269	          );
   270	        }
   271	
   272	        const replacementExists = links.some(
   273	          (link) => link.companyId === replacementPrimaryId,
   274	        );
   275	
   276	        if (!replacementExists) {
   277	          throw this.createInvalidLinkStateException(
   278	            'Replacement primary company must already be linked to the contact.',
   279	          );
   280	        }
   281	      }
   282	
   283	      await linkRepository.delete({ contactId, companyId });
   284	
   285	      if (replacementPrimaryId) {
   286	        const replacementLink = await linkRepository.findOne({
   287	          where: { contactId, companyId: replacementPrimaryId },
   288	        });
   289	
   290	        if (!replacementLink) {
   291	          throw this.createInvalidLinkStateException(
   292	            'Replacement primary company must already be linked to the contact.',
   293	          );
   294	        }
   295	
   296	        await linkRepository
   297	          .createQueryBuilder()
   298	          .update(ContactCompanyLinkEntity)
   299	          .set({ isPrimary: false })
   300	          .where('"contactId" = :contactId', { contactId })
   301	          .execute();
   302	
   303	        await linkRepository.update(
   304	          { contactId, companyId: replacementPrimaryId },
   305	          { isPrimary: true },
   306	        );
   307	      }
   308	
   309	      const remainingLinks = await linkRepository.find({ where: { contactId } });
   310	      const primaryCount = remainingLinks.filter((link) => link.isPrimary).length;
   311	
   312	      if (primaryCount !== 1) {
   313	        throw this.createInvalidLinkStateException(
   314	          'Exactly one primary company link must remain after detach.',
   315	        );
   316	      }
   317	    });
   318	
   319	    return this.getContactById(contactId);
   320	  }
