   410	  private async hydrateContacts(contacts: ContactEntity[]): Promise<ContactResponse[]> {
   411	    if (contacts.length === 0) {
   412	      return [];
   413	    }
   414	
   415	    const linksByContactId = await this.getCompanyLinksByContactIds(
   416	      contacts.map((contact) => contact.id),
   417	    );
   418	
   419	    return contacts.map((contact) => {
   420	      const contactLinks = linksByContactId.get(contact.id) ?? [];
   421	      const primaryLink = contactLinks.find((link) => link.isPrimary);
   422	
   423	      return {
   424	        ...contact,
   425	        primaryCompanyId: primaryLink?.companyId ?? null,
   426	        companies: contactLinks.map((link) => ({
   427	          id: link.companyId,
   428	          name: link.companyName,
   429	        })),
   430	      };
   431	    });
   432	  }
   433	
   434	  private async getCompanyLinksByContactIds(
   435	    contactIds: string[],
   436	  ): Promise<Map<string, CompanyLinkRow[]>> {
   437	    if (contactIds.length === 0) {
   438	      return new Map();
   439	    }
   440	
   441	    const rows = await this.contactRepository.manager.query<CompanyLinkRow[]>(
   442	      `
   443	        SELECT
   444	          link."contactId" AS "contactId",
   445	          link."companyId" AS "companyId",
   446	          link."isPrimary" AS "isPrimary",
   447	          company."name" AS "companyName"
   448	        FROM "contact_company_links" link
   449	        INNER JOIN "companies" company
   450	          ON company.id = link."companyId"
   451	        WHERE link."contactId" = ANY($1)
   452	        ORDER BY link."contactId", link."isPrimary" DESC, company."name" ASC
   453	      `,
   454	      [contactIds],
   455	    );
   456	
   457	    const linkMap = new Map<string, CompanyLinkRow[]>();
   458	
   459	    for (const row of rows) {
   460	      const existing = linkMap.get(row.contactId) ?? [];
   461	      existing.push(row);
   462	      linkMap.set(row.contactId, existing);
   463	    }
   464	
   465	    return linkMap;
   466	  }
