     2	
     3	// Thrown by request() for both network failures (status undefined) and non-2xx
     4	// HTTP responses (status set). isTransportError() below is the single source of
     5	// truth for "infra-level failure the global interceptor should toast" vs.
     6	// "business error the calling page should handle and display itself".
     7	export class RequestError extends Error {
     8	  constructor(message, status, options = {}) {
     9	    super(message);
    10	    this.name = "RequestError";
    11	    this.status = status;
    12	    this.code = options.code;
    13	    this.details = options.details;
    14	  }
    15	}
    16	
    17	// Network failures (fetch itself rejected, no HTTP response at all) and 5xx
    18	// server errors aren't meaningful to a specific page/action, so the global
    19	// interceptor (see App.jsx) shows a generic toast for these. Every other
    20	// status (400/401/403/404/409/422/...) is treated as a business error and
    21	// left to the calling component to interpret and display.
    22	export function isTransportError(error) {
    23	  return !error?.status || error.status >= 500;
    24	}
    25	
    26	function buildUrl(path, query) {
    27	  const url = new URL(`${API_BASE_PATH}${path}`, window.location.origin);
    28	
    29	  if (query) {
    30	    Object.entries(query).forEach(([key, value]) => {
    31	      if (value !== undefined && value !== null && value !== "") {
    32	        url.searchParams.set(key, value);
    33	      }
    34	    });
    35	  }
    36	
    37	  return `${url.pathname}${url.search}`;
    38	}
    39	
    40	// vite.config.js proxies /api/* to CRM_BASELINE_API_ORIGIN (backend mounts everything
    41	// under app.setGlobalPrefix('api')), so callers pass paths like '/companies' and this
    42	// prepends the /api prefix + serializes the `query` object as a querystring.
    43	export async function request(path, { query, headers, ...options } = {}) {
    44	  let response;
    45	
    46	  try {
    47	    response = await fetch(buildUrl(path, query), {
    48	      ...options,
    49	      headers: {
    50	        "Content-Type": "application/json",
    51	        ...headers,
    52	      },
    53	    });
    54	  } catch {
    55	    throw new RequestError(
    56	      "Network error, please check your connection and try again.",
    57	      undefined,
    58	    );
    59	  }
    60	
    61	  const text = await response.text();
    62	  const data = text ? JSON.parse(text) : null;
    63	
    64	  if (!response.ok) {
    65	    const message = data?.message || response.statusText || "Request failed";
    66	    throw new RequestError(
    67	      Array.isArray(message) ? message.join(", ") : message,
    68	      response.status,
    69	      {
    70	        code: data?.code,
    71	        details: data?.details,
    72	      },
    73	    );
    74	  }
    75	
    76	  return data;
    77	}
