    14	function handleTransportError(error) {
    15	  if (isTransportError(error)) {
    16	    enqueueSnackbar(error?.message || 'Something went wrong, please try again later.', { variant: 'error' });
    17	  }
    18	}
    19	
    20	const queryClient = new QueryClient({
    21	  queryCache: new QueryCache({ onError: handleTransportError }),
    22	  mutationCache: new MutationCache({ onError: handleTransportError }),
    23	});
